an.outputs = opts.outputs;\n        if (opts?.endTimeNs != null) span.endTimeNs = opts.endTimeNs;\n      }),\n    };\n    mockSpans[id] = span;\n    return span;\n  }),\n  flushTraces: jest.fn().mockResolvedValue(undefined),\n  SpanStatusCode: { OK: 'STATUS_CODE_OK', ERROR: 'STATUS_CODE_ERROR', UNSET: 'STATUS_CODE_UNSET' },\n  SpanType: { LLM: 'LLM', AGENT: 'AGENT', TOOL: 'TOOL', UNKNOWN: 'UNKNOWN' },\n  SpanAttributeKey: { TOKEN_USAGE: 'mlflow.chat.tokenUsage', MESSAGE_FORMAT: 'mlflow.message.format' },\n  TraceMetadataKey: { TRACE_SESSION: 'mlflow.trace.session', TRACE_USER: 'mlflow.trace.user' },\n  TokenUsageKey: { INPUT_TOKENS: 'input_tokens', OUTPUT_TOKENS: 'output_tokens', TOTAL_TOKENS: 'total_tokens' },\n  InMemoryTraceManager: { getInstance: jest.fn(() => ({ getTrace: jest.fn(() => ({ info: mockTraceInfo })) })) },\n}));\n\nimport { processTranscript, reconstructMessages } from '../../workspace/repo/libs/typescript/integrations/qwen-code/src/tracing';\nimport { readTranscript, getLastTurnRecords, getTokenUsage, formatResultDisplay, buildToolResultMap, getMessageText, getFunctionCalls, parseTimestampToNs, isTextPart, isFunctionCallPart, getToolOutput } from '../../workspace/repo/libs/typescript/integrations/qwen-code/src/transcript';\nimport { flushTraces } from '@mlflow/core';\n\nconst FIX = '/tmp/qwentest/fixture.jsonl';\nconst parseNs = (iso: string) => new Date(iso).getTime() * 1e6;\nconst spans = () => Object.values(mockSpans);\nconst byType = (t: string) => spans().filter((s) => s.spanType === t);\n\nbeforeEach(() => { spanCounter = 0; Object.keys(mockSpans).forEach((k) => delete mockSpans[k]); mockTraceInfo.traceMetadata = {}; jest.clearAllMocks(); });\n\ntest('pure helpers', () => {\n  expect(parseTimestampToNs('2026-04-05T10:00:00Z')).toBe(parseNs('2026-04-05T10:00:00Z'));\n  expect(parseTimestampToNs('')).toBeNull();\n  expect(parseTimestampToNs(null)).toBeNull();\n  expect(parseTimestampToNs(undefined)).toBeNull();\n  expect(formatResultDisplay('x')).toBe('x');\n  expect(formatResultDisplay({ a: 1 })).toBe('{\"a\":1}');\n  expect(formatResultDisplay(null)).toBe('');\n  expect(formatResultDisplay(undefined)).toBe('');\n  expect(isTextPart({ text: 'a' } as any)).toBe(true);\n  expect(isTextPart({ functionCall: {} } as any)).toBe(false);\n  expect(isFunctionCallPart({ functionCall: {} } as any)).toBe(true);\n  expect(isFunctionCallPart({ text: 'a' } as any)).toBe(false);\n  const recs = readTranscript(FIX);\n  expect(recs.length).toBe(4);\n  expect(getMessageText(recs[1])).toBe(\"I'll list them.\");\n  expect(getMessageText(recs[1], true)).toBe(\"thinking...\\nI'll list them.\");\n  expect(getFunctionCalls(recs[1])).toEqual([{ id: 'call_1', name: 'ls', args: { path: '.' } }]);\n  expect(getFunctionCalls(recs[0])).toEqual([]);\n  const map = buildToolResultMap(recs);\n  expect(map.size).toBe(1);\n  expect(map.get('call_1')?.uuid).toBe('t1');\n  expect(getToolOutput(recs[2])).toBe('a.txt\\nb.txt');\n  expect(getLastTurnRecords(recs).length).toBe(4);\n  expect(getTokenUsage(recs[1].usageMetadata)).toEqual({ input: 10, output: 5, total: 15 });\n  expect(getTokenUsage(undefined)).toBeNull();\n});\n\ntest('reconstructMessages', () => {\n  const recs = readTranscript(FIX);\n  expect(reconstructMessages(recs, 3)).toEqual([\n    { role: 'user', content: 'list files' },\n    { role: 'assistant', content: null, tool_calls: [{ id: 'call_1', type: 'function', function: { name: 'ls', arguments: '{\"path\":\".\"}' } }] },\n    { role: 'tool', tool_call_id: 'call_1', content: 'a.txt\\nb.txt' },\n  ]);\n});\n\ntest('processTranscript null', async () => {\n  await processTranscript(null);\n  expect(spans().length).toBe(0);\n  expect(flushTraces).not.toHaveBeenCalled();\n});\n\ntest('processTranscript full', async () => {\n  await processTranscript(FIX, 'sess-1');\n  const root = spans().find((s) => s.parentId == null);\n  expect(root.name).toBe('qwen_code_conversation');\n  expect(root.spanType).toBe('AGENT');\n  expect(root.inputs).toBe('list files');\n  expect(root.startTimeNs).toBe(parseNs('2026-04-05T10:00:00Z'));\n  const rootEnd = (root.end as jest.Mock).mock.calls[0][0];\n  expect(rootEnd.outputs).toBe('There are 2 files.');\n  expect(rootEnd.endTimeNs).toBe(parseNs('2026-04-05T10:00:03Z'));\n  // root token usage: input = last assistant prompt (30), output = sum(5+8)=13\n  expect(root.attributes['mlflow.chat.tokenUsage']).toEqual({ input_tokens: 30, output_tokens: 13, total_tokens: 43 });\n\n  const llm = byType('LLM');\n  expect(llm.length).toBe(2);\n  expect(llm[0].inputs).toEqual({ model: 'qwen-max', messages: [{ role: 'user', content: 'list files' }] });\n  expect(llm[0].startTimeNs).toBe(parseNs('2026-04-05T10:00:00Z'));\n  expect(llm[0].endTimeNs).toBe(parseNs('2026-04-05T10:00:01Z'));\n  const llm0End = (llm[0].end as jest.Mock).mock.calls[0][0];\n  expect(llm0End.outputs).toEqual({ choices: [{ message: { role: 'assistant', content: \"I'll list them.\" } }] });\n  expect(llm[0].attributes['mlflow.chat.tokenUsage']).toEqual({ input_tokens: 10, output_tokens: 5, total_tokens: 15 });\n  // llm[1] startTime = preceding record (tool_result at 10:00:02)\n  expect(llm[1].startTimeNs).toBe(parseNs('2026-04-05T10:00:02Z'));\n  expect(llm[1].endTimeNs).toBe(parseNs('2026-04-05T10:00:03Z'));\n\n  const tool = byType('TOOL');\n  expect(tool.length).toBe(1);\n  expect(tool[0].name).toBe('tool_ls');\n  expect(tool[0].inputs).toEqual({ path: '.' });\n  expect(tool[0].attributes.tool_id).toBe('call_1');\n  expect(tool[0].startTimeNs).toBe(parseNs('2026-04-05T10:00:01Z'));\n  expect(tool[0].endTimeNs).toBe(parseNs('2026-04-05T10:00:02Z'));\n  const toolEnd = (tool[0].end as jest.Mock).mock.calls[0][0];\n  expect(toolEnd.outputs).toEqual({ result: 'a.txt\\nb.txt' });\n  expect(tool[0].setStatus).not.toHaveBeenCalled();\n\n  expect(mockTraceInfo.traceMetadata['mlflow.trace.session']).toBe('sess-1');\n  expect(mockTraceInfo.traceMetadata['mlflow.trace.user']).toBeDefined();\n  expect(flushTraces).toHaveBeenCalled();\n});\n"],"version":3}
