tool_result record     → { role: 'tool', tool_call_id, content }\n * - system record          → { role: 'system', content } (skipped if no message)\n */\nexport function reconstructMessages(records: ChatRecord[], targetIndex: number): OpenAIMessage[] {\n  const messages: OpenAIMessage[] = [];\n\n  for (let i = 0; i < targetIndex; i++) {\n    const record = records[i];\n\n    if (record.type === 'user') {\n      messages.push({ role: 'user', content: getMessageText(record) });\n    } else if (record.type === 'assistant') {\n      const functionCalls = getFunctionCalls(record);\n      if (functionCalls.length > 0) {\n        messages.push({\n          role: 'assistant',\n          content: null,\n          tool_calls: functionCalls.map((fc) => ({\n            id: fc.id,\n            type: 'function',\n            function: { name: fc.name, arguments: JSON.stringify(fc.args ?? {}) },\n          })),\n        });\n      } else {\n        messages.push({ role: 'assistant', content: getMessageText(record) });\n      }\n    } else if (record.type === 'tool_result') {\n      messages.push({\n        role: 'tool',\n        tool_call_id: record.toolCallResult?.callId ?? '',\n        content: getToolOutput(record),\n      });\n    } else if (record.type === 'system') {\n      // System records without a message contribute nothing to the history.\n      if (record.message) {\n        messages.push({ role: 'system', content: getMessageText(record) });\n      }\n    }\n  }\n\n  return messages;\n}\n\n/**\n * Read a Qwen Code transcript and emit an MLflow trace.\n *\n * When `transcriptPath` is null, returns immediately without creating spans or\n * flushing. Otherwise builds the AGENT → LLM → TOOL span tree described above.\n */\nexport async function processTranscript(\n  transcriptPath: string | null,\n  sessionId?: string,\n): Promise<void> {\n  if (transcriptPath == null) {\n    return;\n  }\n\n  const records = readTranscript(transcriptPath);\n  const toolResults = buildToolResultMap(records);\n\n  const assistantRecords = records.filter((record) => record.type === 'assistant');\n  const firstUser = records.find((record) => record.type === 'user');\n  const lastAssistant =\n    assistantRecords.length > 0 ? assistantRecords[assistantRecords.length - 1] : undefined;\n\n  // Root span brackets the whole conversation: first user prompt -> final\n  // assistant reply. The prompt/response are passed as raw strings so MLflow\n  // auto-generates the request/response previews.\n  const userPrompt = firstUser ? getMessageText(firstUser) : '';\n  const finalText = lastAssistant ? getMessageText(lastAssistant) : '';\n  const rootStartNs = firstUser ? parseTimestampToNs(firstUser.timestamp) : null;\n  const rootEndNs = lastAssistant ? parseTimestampToNs(lastAssistant.timestamp) : null;\n\n  const rootSpan = startSpan({\n    name: 'qwen_code_conversation',\n    spanType: SpanType.AGENT,\n    inputs: userPrompt,\n    ...(rootStartNs != null ? { startTimeNs: rootStartNs } : {}),\n  });\n\n  // Walk every record; each assistant record produces one LLM span plus a TOOL\n  // span per functionCall part it emits.\n  for (let i = 0; i < records.length; i++) {\n    const record = records[i];\n    if (record.type !== 'assistant') {\n      continue;\n    }\n\n    const model = record.model ?? 'unknown';\n    const recordNs = parseTimestampToNs(record.timestamp);\n    // LLM span covers the API call: from the previous record to this one.\n    const prevNs = i > 0 ? parseTimestampToNs(records[i - 1].timestamp) : null;\n\n    const llmSpan = startSpan({\n      name: 'llm_call',\n      parent: rootSpan,\n      spanType: SpanType.LLM,\n      ...(prevNs != null ? { startTimeNs: prevNs } : {}),\n      inputs: { model, messages: reconstructMessages(records, i) },\n      attributes: { model },\n    });\n\n    const usage = getTokenUsage(record.usageMetadata);\n    if (usage) {\n      llmSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {\n        [TokenUsageKey.INPUT_TOKENS]: usage.input,\n        [TokenUsageKey.OUTPUT_TOKENS]: usage.output,\n        [TokenUsageKey.TOTAL_TOKENS]: usage.total,\n      });\n    }\n\n    llmSpan.end({\n      outputs: {\n        choices: [{ message: { role: 'assistant', content: getMessageText(record) } }],\n      },\n      ...(recordNs != null ? { endTimeNs: recordNs } : {}),\n    });\n\n    // TOOL spans: one per functionCall, ending at its matching tool_result.\n    for (const fc of getFunctionCalls(record)) {\n      const matched = toolResults.get(fc.id);\n      const toolEndNs = matched ? parseTimestampToNs(matched.timestamp) : null;\n\n      const toolSpan = startSpan({\n        name: `tool_${fc.name}`,\n        parent: rootSpan,\n        spanType: SpanType.TOOL,\n        ...(recordNs != null ? { startTimeNs: recordNs } : {}),\n        inputs: fc.args ?? {},\n        attributes: { tool_name: fc.name, tool_id: fc.id },\n      });\n\n      // A cancelled tool call is surfaced as an ERROR span; successful calls\n      // are left in the default (unset) status.\n      if (matched?.toolCallResult?.status === 'cancelled') {\n        toolSpan.setStatus(SpanStatusCode.ERROR, 'Tool call was cancelled');\n      }\n\n      toolSpan.end({\n        outputs: { result: matched ? getToolOutput(matched) : '' },\n        ...(toolEndNs != null ? { endTimeNs: toolEndNs } : {}),\n      });\n    }\n  }\n\n  // Root token usage: input reflects the LAST API call's prompt size (the\n  // running context), output is the sum of everything the model generated.\n  const outputTokens = assistantRecords.reduce(\n    (sum, record) => sum + (record.usageMetadata?.candidatesTokenCount ?? 0),\n    0,\n  );\n  const inputTokens = lastAssistant?.usageMetadata?.promptTokenCount ?? 0;\n  rootSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {\n    [TokenUsageKey.INPUT_TOKENS]: inputTokens,\n    [TokenUsageKey.OUTPUT_TOKENS]: outputTokens,\n    [TokenUsageKey.TOTAL_TOKENS]: inputTokens + outputTokens,\n  });\n\n  // Attach session/user