*\n * Each line of a transcript is a `ChatRecord`. This module provides the pure\n * helpers used to read those records and normalize their Gemini-style `parts`\n * into the shapes MLflow tracing needs (plain text, function calls, tool\n * output, token usage).\n */\n\nimport { readFileSync } from 'node:fs';\nimport type {\n  ChatRecord,\n  GeminiPart,\n  TextPart,\n  FunctionCallPart,\n  FunctionResponsePart,\n} from './types.js';\n\nexport const NANOSECONDS_PER_MS = 1e6;\n\n/**\n * Read and parse a Qwen Code JSONL transcript file into ChatRecord objects.\n */\nexport function readTranscript(path: string): ChatRecord[] {\n  const content = readFileSync(path, 'utf-8');\n  return content\n    .split('\\n')\n    .filter((line) => line.trim())\n    .map((line) => JSON.parse(line) as ChatRecord);\n}\n\n/**\n * Parse an ISO 8601 timestamp string to nanoseconds since the Unix epoch\n * (epoch milliseconds * 1,000,000). Returns null for null, undefined, or\n * empty-string input.\n */\nexport function parseTimestampToNs(timestamp: string | null | undefined): number | null {\n  if (!timestamp) {\n    return null;\n  }\n  const ms = new Date(timestamp).getTime();\n  if (isNaN(ms)) {\n    return null;\n  }\n  return ms * NANOSECONDS_PER_MS;\n}\n\n/**\n * Type guard: true when a part carries a `text` property.\n */\nexport function isTextPart(part: GeminiPart): part is TextPart {\n  return part != null && typeof part === 'object' && 'text' in part;\n}\n\n/**\n * Type guard: true when a part carries a `functionCall` property.\n */\nexport function isFunctionCallPart(part: GeminiPart): part is FunctionCallPart {\n  return part != null && typeof part === 'object' && 'functionCall' in part;\n}\n\n/**\n * Type guard: true when a part carries a `functionResponse` property.\n */\nexport function isFunctionResponsePart(part: GeminiPart): part is FunctionResponsePart {\n  return part != null && typeof part === 'object' && 'functionResponse' in part;\n}\n\n/**\n * Extract the text content of a record's message.\n *\n * Joins all text parts with a newline. Thought parts (thought=true) are\n * excluded by default and included only when `includeThoughts` is true.\n * A plain string message is returned as-is. functionCall / functionResponse\n * parts contribute no text and are skipped.\n */\nexport function getMessageText(record: ChatRecord, includeThoughts = false): string {\n  const message = record.message;\n  if (!message) {\n    return '';\n  }\n  if (typeof message === 'string') {\n    return message;\n  }\n  const parts = message.parts ?? [];\n  return parts\n    .filter(isTextPart)\n    .filter((part) => includeThoughts || !part.thought)\n    .map((part) => part.text)\n    .join('\\n');\n}\n\n/**\n * Extract all functionCall parts from a record's message.\n * Returns an empty array for records with no message or no functionCall parts.\n */\nexport function getFunctionCalls(\n  record: ChatRecord,\n): Array<{ id: string; name: string; args?: Record<string, any> }> {\n  const message = record.message;\n  if (!message || typeof message === 'string') {\n    return [];\n  }\n  const parts = message.parts ?? [];\n  return parts.filter(isFunctionCallPart).map((part) => ({\n    id: part.functionCall.id,\n    name: part.functionCall.name,\n    args: part.functionCall.args,\n  }));\n}\n\n/**\n * Build a Map from `toolCallResult.callId` to the tool_result record.\n * Only records of type 'tool_result' are included.\n */\nexport function buildToolResultMap(records: ChatRecord[]): Map<string, ChatRecord> {\n  const map = new Map<string, ChatRecord>();\n  for (const record of records) {\n    if (record.type === 'tool_result' && record.toolCallResult?.callId) {\n      map.set(record.toolCallResult.callId, record);\n    }\n  }\n  return map;\n}\n\n/**\n * Normalize a resultDisplay value to a string. Strings pass through unchanged,\n * objects are JSON-stringified, and null/undefined become the empty string.\n */\nexport function formatResultDisplay(display: any): string {\n  if (display == null) {\n    return '';\n  }\n  if (typeof display === 'string') {\n    return display;\n  }\n  return JSON.stringify(display);\n}\n\n/**\n * Extract tool output from a tool_result record.\n *\n * Prefers `toolCallResult.resultDisplay` (normalized via formatResultDisplay).\n * When resultDisplay is absent, falls back to JSON.stringify of the\n * functionResponse.response found in the message parts. Returns an empty\n * string when neither is available.\n */\nexport function getToolOutput(record: ChatRecord): string {\n  const resultDisplay = record.toolCallResult?.resultDisplay;\n  if (resultDisplay != null) {\n    return formatResultDisplay(resultDisplay);\n  }\n\n  const message = record.message;\n  if (message && typeof message !== 'string') {\n    for (const part of message.parts ?? []) {\n      if (isFunctionResponsePart(part)) {\n        return JSON.stringify(part.functionResponse.response);\n      }\n    }\n  }\n  return '';\n}\n\n/**\n * Return the records belonging to the last turn: a slice starting at the last\n * record whose type is 'user' and continuing through the end of the array.\n * Returns the full array when no user record is present.\n */\nexport function getLastTurnRecords(records: ChatRecord[]): ChatRecord[] {\n  for (let i = records.length - 1; i >= 0; i--) {\n    if (records[i].type === 'user') {\n      return records.slice(i);\n    }\n  }\n  return records;\n}\n\n/**\n * Map a usageMetadata object into MLflow's {input, output, total} shape.\n * Returns null when the argument is undefined or missing.\n */\nexport function getTokenUsage(\n  usageMetadata: any,\n): { input: number; output: number; total: number } | null {\n  if (usageMetadata == null) {\n    return null;\n  }\n  return {\n    input: usageMetadata.promptTokenCount,\n    output: usageMetadata.candidatesTokenCount,\n    total: usageMetadata.totalTokenCount,\n  };\n}\n"],"version":3}
